mapper.update:
UPDATE ${tableName}
SET state = #{state}
WHERE enterprise_code = #{enterpriseCode}
  AND delete_flag = 'f'
  AND primary_key = #{afterSaleCode}

mapper.select:
SELECT primary_key, contract_code, buss_number, buyer_enterprise, buyer_enterprise_code, buyer_contract_code, buyer_contact_name, seller, state, business_belong, enterprise_code, create_time, update_time, delete_flag FROM ${tableName} WHERE enterprise_code= #{enterpriseCode} AND delete_flag= 'f'
AND buss_number LIKE '%'|| #{bussNumber} ||'%'
AND buyer_enterprise LIKE '%'|| #{buyerEnterprise} ||'%'
AND seller in
#{seller}
AND state = #{state}
AND business_belong = #{businessBelong}
${dataScopeParams.dataScope}
ORDER BY id DESC
